messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Humanoid Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
    <!-- Import Map for Three.js r160 ES Module -->
    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CYCLE_DURATION = 10; // Total seconds
        const STAND_STILL = 2;
        const WALK_TIME = 3;
        const RUN_TIME = 3;
        const SPEED_WALK = 4;
        const SPEED_RUN = 10;
        const ROTATION_SPEED = Math.PI * 2 / CYCLE_DURATION;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);
        scene.fog = new THREE.Fog(0x222222, 10, 30);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        // Side-on camera position
        camera.position.set(0, 3, 12);
        camera.lookAt(0, 2, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Materials ---
        const skinMaterial = new THREE.MeshStandardMaterial({ color: 0x88ccff });
        const clothesMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const shoeMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.8 });

        // --- The Humanoid (Low Poly) ---
        const humanoid = new THREE.Group();

        // 1. Torso
        const torsoGeo = new THREE.BoxGeometry(1, 1.2, 0.4);
        const torso = new THREE.Mesh(torsoGeo, clothesMaterial);
        torso.position.y = 3.0;
        torso.castShadow = true;
        humanoid.add(torso);

        // 2. Head
        const headGeo = new THREE.BoxGeometry(0.5, 0.5, 0.5);
        const head = new THREE.Mesh(headGeo, skinMaterial);
        head.position.y = 1.0; // Relative to torso
        head.castShadow = true;
        torso.add(head);

        // Helper to create limbs
        function createLimb(width, height, x, y, z, isLeg = false) {
            const geometry = new THREE.BoxGeometry(width, height, width);
            const material = isLeg ? clothesMaterial : skinMaterial;
            const limb = new THREE.Mesh(geometry, material);

            // Pivot point setup: We want the limb to rotate from the shoulder/hip
            limb.position.set(x, y, z);

            // Adjust pivot offset so rotation happens at the top of the limb
            // If we rotate the mesh, it rotates around its center. 
            // We want to rotate around the top. So we offset geometry or use a pivot group.
            // Simplest for low poly: Offset the mesh geometry up by half its length.
            const offset = height / 2;
            limb.position.y += offset;

            const pivot = new THREE.Object3D();
            pivot.position.set(0, -offset, 0); // Move pivot back to the attachment point
            pivot.add(limb);

            return { mesh: pivot };
        }

        // 3. Arms (Pivots)
        const leftArm = createLimb(0.25, 1.0, -0.6, 0.6, 0);
        const rightArm = createLimb(0.25, 1.0, 0.6, 0.6, 0);
        torso.add(leftArm.mesh);
        torso.add(rightArm.mesh);

        // 4. Legs (Pivots)
        const leftLeg = createLimb(0.3, 1.2, -0.3, -0.6, 0, true);
        const rightLeg = createLimb(0.3, 1.2, 0.3, -0.6, 0, true);
        torso.add(leftLeg.mesh);
        torso.add(rightLeg.mesh);

        // 5. Feet (Children of Legs)
        function createFoot(x, z) {
            const footGeo = new THREE.BoxGeometry(0.4, 0.2, 0.8);
            const foot = new THREE.Mesh(footGeo, shoeMaterial);
            foot.position.set(x, 0, z); // Relative to leg bottom
            foot.castShadow = true;
            return foot;
        }
        leftLeg.mesh.add(createFoot(-0.1, 0.2));
        rightLeg.mesh.add(createFoot(0.1, 0.2));

        scene.add(humanoid);

        // --- Treadmill Ground ---
        const groundGeo = new THREE.PlaneGeometry(10, 20);
        const ground = new THREE.Mesh(groundGeo, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // --- Animation State ---
        let time = 0; // Total time in seconds
        let currentPhase = 'stand'; // stand, walk, run
        let phaseTimer = 0;

        // --- Animation Logic ---
        function updateAnimation(delta) {
            time += delta;

            // Normalize time within cycle
            const cycleTime = time % CYCLE_DURATION;

            // Reset phases based on cycle time
            if (cycleTime < STAND_STILL) {
                currentPhase = 'stand';
            } else if (cycleTime < STAND_STILL + WALK_TIME) {
                currentPhase = 'walk';
            } else {
                currentPhase = 'run';
            }

            // Common setup
            humanoid.rotation.y += ROTATION_SPEED * delta; // Rotate slowly to show 3D aspect

            // --- Phase Specific Logic ---

            // 1. Stand Still (0 - 2s)
            if (currentPhase === 'stand') {
                leftArm.mesh.rotation.x = 0;
                rightArm.mesh.rotation.x = 0;
                leftLeg.mesh.rotation.x = 0;
                rightLeg.mesh.rotation.x = 0;
                torso.rotation.x = 0;
            }

            // 2. Walk (2 - 5s)
            else if (currentPhase === 'walk') {
                const walkSpeed = 2.5 * delta; // Slower, controlled
                const angle = Math.sin(time * SPEED_WALK);

                // Arms swing opposite to legs
                leftArm.mesh.rotation.x = -angle * 0.8;
                rightArm.mesh.rotation.x = angle * 0.8;

                // Legs swing forward/back
                leftLeg.mesh.rotation.x = angle * 0.8;
                rightLeg.mesh.rotation.x = -angle * 0.8;

                // Slight bounce
                torso.position.y = 3.0 + Math.abs(Math.sin(time * SPEED_WALK)) * 0.1;
                torso.rotation.x = Math.sin(time * SPEED_WALK) * 0.05;
            }

            // 3. Run (5 - 8s)
            else if (currentPhase === 'run') {
                const runSpeed = 6.0 * delta; // Faster
                const angle = Math.sin(time * SPEED_RUN);

                // Arms swing high and fast
                leftArm.mesh.rotation.x = -angle * 1.5;
                rightArm.mesh.rotation.x = angle * 1.5;

                // Legs kick higher and faster
                // We need to ensure full range of motion for running
                leftLeg.mesh.rotation.x = angle * 1.2;
                rightLeg.mesh.rotation.x = -angle * 1.2;

                // Knees bend? (Simplified: just rotate at hip)

                // Forward lean
                torso.rotation.x = 0.3; // Constant lean forward
                torso.position.y = 2.8; // Lower center of gravity
            }
        }

        // --- Render Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const delta = clock.getDelta();

            updateAnimation(delta);
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start immediately
        animate();

    </script>
</body>
</html>
```
